import 'package:flutter/material.dart';
import '../core/services/api_client.dart';
import '../core/theme/app_theme.dart';

class WalletScreen extends StatefulWidget { const WalletScreen({super.key}); @override State<WalletScreen> createState()=>_WalletScreenState(); }
class _WalletScreenState extends State<WalletScreen>{ Map<String,dynamic>? data; bool loading=true; String? error;
 @override void initState(){super.initState();load();}
 Future<void> load()async{setState(()=>loading=true);try{data=Map<String,dynamic>.from(await ApiClient.get('/wallet'));}catch(e){error=e.toString();}finally{if(mounted)setState(()=>loading=false);}}
 Future<void>redeem()async{final points=TextEditingController(text:'100');final ok=await showDialog<bool>(context:context,builder:(_)=>AlertDialog(title:const Text('Redeem loyalty points'),content:TextField(controller:points,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Points (multiples of 100)')),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Cancel')),ElevatedButton(onPressed:()=>Navigator.pop(context,true),child:const Text('Redeem'))]));if(ok!=true)return;try{await ApiClient.post('/loyalty/redeem',{'points':int.parse(points.text)});if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Points redeemed to wallet')));load();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}}
 @override Widget build(BuildContext c){if(loading)return const Scaffold(body:Center(child:CircularProgressIndicator()));return Scaffold(appBar:AppBar(title:const Text('Wallet & Loyalty')),body:error!=null?Center(child:Text(error!)):RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(16),children:[Container(padding:const EdgeInsets.all(22),decoration:BoxDecoration(borderRadius:BorderRadius.circular(24),gradient:const LinearGradient(colors:[AppTheme.deep,AppTheme.teal])),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('FoodHub Wallet',style:TextStyle(color:Colors.white70)),const SizedBox(height:8),Text('₱${data?['wallet']?['balance']??'0.00'}',style:const TextStyle(color:Colors.white,fontSize:34,fontWeight:FontWeight.w800)),const SizedBox(height:12),Text('Currency: ${data?['wallet']?['currency']??'PHP'}',style:const TextStyle(color:Colors.white70))])),const SizedBox(height:16),Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.stars_rounded)),title:Text('${data?['loyalty']?['points']??0} points'),subtitle:Text('Tier: ${data?['loyalty']?['tier']??'bronze'}'),trailing:ElevatedButton(onPressed:(data?['loyalty']?['points']??0)>=100?redeem:null,child:const Text('Redeem')))),const SizedBox(height:12),ListTile(title:const Text('100 points = ₱1 wallet credit'),subtitle:const Text('Rewards are earned from completed paid orders.'))])));}
}
